#!/usr/bin/env node
/**
 * AUTM-1870, AUTM-2147: writes src/lib/vehicle-make-logos.ts, the make marks
 * the vehicle picker and the merchant's job ticket draw, from Simple Icons
 * (CC0-1.0). simple-icons is a devDependency pinned to an exact version and
 * never a runtime one: its 3,400 icons would ship to every consumer for the
 * few dozen we use, so only the path data is copied into the generated file,
 * which is committed.
 *
 *   pnpm install
 *   node scripts/gen-vehicle-make-logos.mjs          # node_modules/simple-icons
 *   node scripts/gen-vehicle-make-logos.mjs path/to/package
 *
 * Monochrome, so the consumer tints it with a token (currentColor). A make
 * Simple Icons does not carry has no entry: the picker draws its monogram and
 * a caller that asks hasVehicleMakeLogo() keeps its own icon. Logos come from
 * Simple Icons only, never anywhere else and never hotlinked.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const pkg = process.argv[2] ?? 'node_modules/simple-icons'
const { version } = JSON.parse(readFileSync(join(pkg, 'package.json'), 'utf8'))

/* Our make slug (vehicleSlug of the catalog name) -> the Simple Icons slug. */
const MAKES = {
    audi: 'audi', bmw: 'bmw', ford: 'ford', honda: 'honda', hyundai: 'hyundai', jeep: 'jeep', kia: 'kia',
    mazda: 'mazda', mg: 'mg', mini: 'mini', mitsubishi: 'mitsubishi', nissan: 'nissan', peugeot: 'peugeot',
    porsche: 'porsche', ram: 'ram', renault: 'renault', skoda: 'skoda', subaru: 'subaru', suzuki: 'suzuki',
    tesla: 'tesla', toyota: 'toyota', volkswagen: 'volkswagen', volvo: 'volvo',
    /* AUTM-2147: the makes AUTM-2005 added that Simple Icons carries. Left
       out on purpose: Proton (Simple Icons' "proton" is Proton AG, the
       mail company) and Mahindra (its icon is the group wordmark, a 2px
       strip at this size, not the badge on the car). */
    'aston-martin': 'astonmartin', bentley: 'bentley', bugatti: 'bugatti', cadillac: 'cadillac',
    chevrolet: 'chevrolet', chrysler: 'chrysler', citroen: 'citroen', ferrari: 'ferrari', fiat: 'fiat',
    infiniti: 'infiniti', koenigsegg: 'koenigsegg', lamborghini: 'lamborghini', maserati: 'maserati',
    mclaren: 'mclaren', opel: 'opel', polestar: 'polestar', 'rolls-royce': 'rollsroyce', smart: 'smart',
    tata: 'tata',
}

const entries = Object.entries(MAKES).map(([ours, theirs]) => {
    const svg = readFileSync(join(pkg, 'icons', `${theirs}.svg`), 'utf8')
    if (!svg.includes('viewBox="0 0 24 24"')) throw new Error(`${theirs}: not a 24 x 24 icon`)
    const paths = [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1])
    if (paths.length !== 1) throw new Error(`${theirs}: expected one path, found ${paths.length}`)
    return `    '${ours}': '${paths[0]}',`
})

writeFileSync(
    'src/lib/vehicle-make-logos.ts',
    `/**
 * AUTM-1870, AUTM-2147: the make marks VehiclePicker and the merchant's job
 * ticket draw (Don approved real make logos, 2026-10-14; single-colour marks
 * from Simple Icons, 2026-11-12), from Simple Icons ${version}. GENERATED by
 * scripts/gen-vehicle-make-logos.mjs: do not edit by hand.
 *
 * Simple Icons' data is CC0-1.0; the marks themselves are their makers'
 * trademarks, shown only to name the customer's own car. Each is one path on
 * a 24 x 24 box, drawn in currentColor so a token tints it in both themes.
 * Keys are the catalog make's vehicleSlug. A make missing here (BYD, Isuzu,
 * Holden, GWM, Chery and others Simple Icons does not carry) draws a monogram
 * in the picker, and hasVehicleMakeLogo() is false for it.
 */
export const VEHICLE_MAKE_LOGO_SOURCE = 'simple-icons@${version}'

export const VEHICLE_MAKE_LOGO_PATHS: Record<string, string> = {
${entries.join('\n')}
}
`
)
console.log(`wrote ${entries.length} marks from simple-icons@${version}`)
